export function buildPlanter({ size = 0.6, height = 0.5, wall = 0.05 } = {}) {
  const group = new THREE.Group();
  const clay = new THREE.MeshStandardMaterial({ color: 0xb0623d, roughness: 0.9 });
  const soil = new THREE.MeshStandardMaterial({ color: 0x3d2b1f, roughness: 1 });

  const inner = size - wall * 2;

  // Floor.
  const floor = new THREE.Mesh(new THREE.BoxGeometry(size, wall, size), clay);
  floor.position.y = wall / 2;

  // Walls.
  const wallY = height / 2;
  const front = new THREE.Mesh(new THREE.BoxGeometry(size, height, wall), clay);
  front.position.set(0, wallY, size / 2 - wall / 2);
  const backSide = front.clone();
  backSide.position.z = -(size / 2 - wall / 2);
  const left = new THREE.Mesh(new THREE.BoxGeometry(wall, height, inner), clay);
  left.position.set(-(size / 2 - wall / 2), wallY, 0);
  const right = left.clone();
  right.position.x = size / 2 - wall / 2;

  // Soil sits just below the rim.
  const soilBlock = new THREE.Mesh(new THREE.BoxGeometry(inner, height - wall * 2, inner), soil);
  soilBlock.position.y = height - wall - (height - wall * 2) / 2;

