import path from 'node:path';
import * as THREE from 'three';
import { GLTFExporter } from 'three/examples/jsm/exporters/GLTFExporter.js';
import { buildLantern } from '../src/assets/lantern.js';
import { buildBench } from '../src/assets/bench.js';
import { buildPlanter } from '../src/assets/planter.js';

