import path from 'node:path';

const TOLERANCE = 1e-3;

/**
 * Re-reads every glTF listed in <dir>/manifest.json and validates:
 *   - gltf.asset.version === '2.0'
 *   - at least one accessor exists and every accessor has count > 0
 *   - manifest dimensions match the POSITION accessor min/max bounding box
 *     within 1e-3
 *
 * @param {string} dir Directory containing *.gltf files and manifest.json.
 * @returns {Promise<{ok: boolean, problems: string[]}>}
 * @throws {Error} if any check fails (message lists every problem).
 */
export async function validateKit(dir) {
  const manifestPath = path.join(dir, 'manifest.json');
  const manifest = JSON.parse(await readFile(manifestPath, 'utf8'));
  const problems = [];

  if (!Array.isArray(manifest.assets) || manifest.assets.length === 0) {
    throw new Error('manifest.json contains no assets');
  }

  for (const entry of manifest.assets) {
    const file = path.join(dir, entry.file);
    let gltf;
    try {
      gltf = JSON.parse(await readFile(file, 'utf8'));
    } catch (err) {
      problems.push(`${entry.name}: cannot read ${entry.file} (${err.message})`);
      continue;
    }

    // asset.version must be present and be glTF 2.0.
    if (gltf.asset?.version !== '2.0') {
      problems.push(`${entry.name}: asset.version is ${JSON.stringify(gltf.asset?.version)}, expected "2.0"`);
    }

    // Accessor counts > 0.
    const accessors = gltf.accessors ?? [];
    if (accessors.length === 0) {
      problems.push(`${entry.name}: no accessors found`);
    }
    for (let i = 0; i < accessors.length; i++) {
      if (!(accessors[i].count > 0)) {
        problems.push(`${entry.name}: accessor ${i} has count ${accessors[i].count}, expected > 0`);
      }
    }

    // Bounding box from all POSITION accessors referenced by mesh primitives.
    const positionAccessors = new Set();
    for (const mesh of gltf.meshes ?? []) {
      for (const prim of mesh.primitives ?? []) {
        const posIndex = prim.attributes?.POSITION;
        if (posIndex !== undefined) positionAccessors.add(posIndex);
      }
    }
    if (positionAccessors.size === 0) {
      problems.push(`${entry.name}: no POSITION accessors referenced by meshes`);
      continue;
    }

    const min = [Infinity, Infinity, Infinity];
    const max = [-Infinity, -Infinity, -Infinity];
    for (const index of positionAccessors) {
      const acc = accessors[index];
      if (!acc?.min || !acc?.max) {
        problems.push(`${entry.name}: POSITION accessor ${index} lacks min/max`);
        continue;
      }
      for (let axis = 0; axis < 3; axis++) {
        min[axis] = Math.min(min[axis], acc.min[axis]);
        max[axis] = Math.max(max[axis], acc.max[axis]);
      }
    }

    const size = min.map((m, axis) => max[axis] - m);
    const dims = entry.dimensions ?? {};
    for (const [axis, key] of [['x', 'width'], ['y', 'height'], ['z', 'depth']]) {
      const actual = size[axis];
      const expected = dims[key];
      if (typeof expected !== 'number') {
        problems.push(`${entry.name}: manifest is missing dimensions.${key}`);
      } else if (Math.abs(actual - expected) > TOLERANCE) {
        problems.push(
          `${entry.name}: dimensions.${key} mismatch — manifest ${expected} vs accessor bbox ${actual} (diff ${Math.abs(actual - expected)})`,
        );
      }
    }
  }

  if (problems.length > 0) {
    throw new Error(`kit validation failed:\n  - ${problems.join('\n  - ')}`);
  }
  return { ok: true, problems: [] };
}
